fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let total: i32 = t / 60 + 23 * 3600 + 59 * 60 + 30;
    let hh: i32 = (total / 3600) % 24;
    let mm: i32 = (total / 60) % 60;
    let ss: i32 = total % 60;
    let vals = [hh / 10, hh % 10, mm / 10, mm % 10, ss / 10, ss % 10];
    let bits = [2, 4, 3, 4, 3, 4];
    host::display::clear(0x06060a);
    let colw: i32 = w / 8;
    let cell: i32 = 44;
    let y0: i32 = h / 2 + 60;
    let mut c: i32 = 0;
    while c < 6 {
        let x: i32 = colw / 2 + c * colw + (c / 2) * colw / 2;
        let v: i32 = vals[c];
        let mut b: i32 = 0;
        while b < bits[c] {
            let y: i32 = y0 - b * cell;
            if ((v >> b) & 1) == 1 {
                host::display::fill_rect(x, y, 24, 24, 0x00e0d0);
            } else {
                host::display::fill_rect(x, y, 24, 24, 0x242430);
                host::display::fill_rect(x + 2, y + 2, 20, 20, 0x06060a);
            }
            b = b + 1;
        }
        host::display::draw_number(x + 6, y0 + cell, v, 0x808080, 2);
        c = c + 1;
    }
    host::display::draw_string(colw / 2, h - 24, "H H M M S S", 0x606060, 1);
    host::display::present();
}
